// =============================================================================
// Flatten @lynx-js/web-core's `in_shadow.css` into a single CSS string module.
//
// Why this exists — the shadow-root layout CSS problem:
//
// `@lynx-js/web-core` injects layout CSS into every <lynx-view> shadow root by
// importing it Vite-style and Blob-ing it into a <link>:
//
//   import IN_SHADOW_CSS from '../../../css/in_shadow.css?inline';   // web-core
//   new Blob([IN_SHADOW_CSS], { type: 'text/css' })  →  <link href=blob:…>
//
// Under Turbopack/Webpack (Next), `?inline` does NOT yield the CSS *string* —
// the `.css` module's default export is `undefined`, so the Blob becomes the
// literal text "undefined" and the shadow root gets no web-elements layout CSS
// (flex defaults, `flex-direction`, etc. silently break).
//
// On top of that, `in_shadow.css` starts with
//   @import url("@lynx-js/web-elements/index.css");
// a *bare package specifier* that a Blob-URL stylesheet could never resolve at
// runtime anyway (no base URL, no node resolution).
//
// So we flatten the whole @import tree (bare + relative, recursively) into one
// self-contained string and emit it as a `.ts` module. `lynx-player.tsx` then
// injects that string into each shadow root itself — bundler-agnostic, and it
// sidesteps web-core's broken `?inline` path entirely.
//
// Run via `pnpm lynx:shadow-css` (wired into predev / prebuild).
// =============================================================================

import { createRequire } from "module";
import fs from "fs";
import path from "path";

const require = createRequire(import.meta.url);

/** Resolve an @import target (bare/scoped or relative) to an absolute file. */
function resolveImport(spec, fromDir) {
  if (spec.startsWith(".") || spec.startsWith("/")) {
    return path.resolve(fromDir, spec);
  }
  let pkg, sub;
  if (spec.startsWith("@")) {
    const parts = spec.split("/");
    pkg = parts.slice(0, 2).join("/");
    sub = parts.slice(2).join("/");
  } else {
    const parts = spec.split("/");
    pkg = parts[0];
    sub = parts.slice(1).join("/");
  }
  const pkgRoot = path.dirname(require.resolve(`${pkg}/package.json`));
  return path.join(pkgRoot, sub);
}

// Matches `@import url("…");`, `@import url(…);`, and `@import "…";`.
const IMPORT_RE =
  /@import\s+(?:url\(\s*(['"]?)([^'")]+)\1\s*\)|(['"])([^'"]+)\3)[^;]*;/g;

function flatten(file, seen) {
  let abs;
  try {
    abs = fs.realpathSync(file);
  } catch {
    return `/* missing: ${file} */\n`;
  }
  if (seen.has(abs)) return ""; // dedupe (CSS defaults are idempotent)
  seen.add(abs);

  const dir = path.dirname(abs);
  const css = fs.readFileSync(abs, "utf8");

  return css.replace(IMPORT_RE, (_m, _q1, u1, _q2, u2) => {
    const spec = (u1 || u2).split(/[?#]/)[0]; // strip any query/hash
    try {
      const target = resolveImport(spec, dir);
      return `\n/* ← ${spec} */\n${flatten(target, seen)}`;
    } catch (e) {
      return `/* unresolved @import ${spec}: ${e.message} */\n`;
    }
  });
}

const entry = path.join(
  path.dirname(require.resolve("@lynx-js/web-core/package.json")),
  "css",
  "in_shadow.css",
);

const flat = flatten(entry, new Set()).trim();

const outFile = path.join(
  process.cwd(),
  "systems",
  "windows",
  "lib",
  "lynx-shadow-css.ts",
);

const banner =
  "// AUTO-GENERATED by scripts/lynx-shadow-css-bundle.mjs — do not edit by hand.\n" +
  "// Flattened @lynx-js/web-core `in_shadow.css` (+ web-elements @imports) as a\n" +
  "// string, injected into each <lynx-view> shadow root by lynx-player.tsx.\n";

fs.writeFileSync(
  outFile,
  `${banner}export const LYNX_SHADOW_CSS = ${JSON.stringify(flat)};\n`,
);

console.log(
  `lynx:shadow-css → ${path.relative(process.cwd(), outFile)} (${flat.length} bytes CSS)`,
);
